import{z as c,x as E,o,c as n,q as t,j as l,D as a,d as r,s as T,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"GOT 与 PLT","description":"","frontmatter":{"title":"GOT 与 PLT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/got-plt.md","filePath":"cs/got-plt.md","lastUpdated":1791063341000}'),s={name:"cs/got-plt.md"};function p(A,e,L,_,B,P){const d=E("Mermaid");return o(),n("div",null,[e[2]||(e[2]=t('<h1 id="got-与-plt" tabindex="-1">GOT 与 PLT <a class="header-anchor" href="#got-与-plt" aria-label="Permalink to &quot;GOT 与 PLT&quot;">​</a></h1><div class="epigraph"><p>GOT 是可写的地址表；PLT 是每符号一小段桩，第一次跳进解析器，以后经 GOT 直达。延迟绑定把重定位从加载时刻挪到首次调用。</p><footer>—— 据 System V ABI；ELF 规范；Levine, Linkers and Loaders, 2000 整理</footer></div><p>上一课<a href="/cs/link-reloc">链接与重定位</a>把多个 <code>.o</code> 合成可执行或共享对象，并声明 PLT/GOT 的运行时跳板不在那一课。PIC 已要求外部访问走间接。本课不重做节合并。缺口是两张表的形状：GOT 条目存绝对地址；PLT 条目是可执行桩。加载器下一课才 <code>mmap</code> 并把延迟绑定跑起来；本课把编译/链接产物侧钉死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享库里 <code>call printf</code> 在链接期不知道 <code>printf</code> 的最终虚址，且每个进程基址不同。GOT：链接器为符号分配槽，代码 <code>load t, GOT[printf]; jalr t</code>。启动时动态链接器填槽。若每个调用都走解析，启动慢。PLT：桩先 <code>jmp *GOT[printf]</code>；槽的初值指回桩的解析路径，解析器写完 GOT 再跳到真 <code>printf</code>。之后 GOT 已是真地址，桩变成一次间接跳。</p><p>缺口是这份跳板，不是再解析静态强符号。数据符号通常只走 GOT（或 copy reloc），没有 PLT。</p><h3 id="plt-不是函数的别名" tabindex="-1">PLT 不是函数的别名 <a class="header-anchor" href="#plt-不是函数的别名" aria-label="Permalink to &quot;PLT 不是函数的别名&quot;">​</a></h3><p>同一 <code>printf</code> 一个 PLT 项，多个调用点进同一桩。不要为每个调用点复制解析逻辑。位置无关下桩自己也用 GOT 自寻址。</p><p><span class="marginnote">System V ABI 的过程链接表。ELF <code>R_*_JUMP_SLOT</code> / <code>R_*_GLOB_DAT</code>。Levine 第 10 章动态链接。load-dynlink 课会从进程映像再讲一遍绑定时机；本课只建表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链接器为未决函数符号建 PLT+GOT 槽，为数据符号建 GOT 槽。重定位项指向槽而非 <code>.text</code> 里的立即数（PIC）。可执行文件对 <code>libc</code> 的引用默认走 PLT，除非 <code>-static</code>。</p>',11)),(o(),l(i,null,{default:a(()=>[T(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22call%20foo%22%5D%20--%3E%20PLT%5B%22PLT%20%E6%A1%A9%22%5D%0A%20%20PLT%20--%3E%20GOT%5B%22GOT%5Bfoo%5D%22%5D%0A%20%20GOT%20--%3E%7C%22%E6%9C%AA%E5%A1%AB%22%7C%20LD%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20LD%20--%3E%20GOT%0A%20%20GOT%20--%3E%7C%22%E5%B7%B2%E5%A1%AB%22%7C%20REAL%5B%22foo%20%E7%9C%9F%E5%9C%B0%E5%9D%80%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p>立即绑定（<code>LD_BIND_NOW</code>）加载时填完所有 JUMP_SLOT，不要延迟。安全策略有时要求如此，本课点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GOT 必须可写、通常相对代码有固定位移（或经寄存器）。只读 GOT（RELRO）把填完后的表改只读，减少写 GOT 攻击面——安全课再收。本课要：表在数据段，桩在文本段。</p><p><span class="marginnote">数字实例：一个程序引用 libc 里的 2000 个函数，但实际只调用其中 300 个。延迟绑定让另外 1700 个符号的重定位推迟到「永远不发生」——启动时少做 1700 次符号查找（每次都要哈希查动态符号表、比对字符串）。用 <code>LD_BIND_NOW=1</code> 则 2000 个槽在启动时全部填完，换来更少的启动不确定性。</span></p><p><span class="marginnote">常见误区：初学者容易以为 <code>call printf</code> 直接跳进 libc。实际上第一次调用先落在本程序自己的 PLT 桩上，桩经 GOT 绕道动态链接器做解析，第二次以后才「桩 → GOT → 真函数」两跳直达。理解这一点，<code>gdb</code> 里断在 <code>printf@plt</code> 却看不到 libc 源码就不奇怪了。</span></p>',5)),(o(),l(i,null,{default:a(()=>[T(d,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A6%96%E6%AC%A1%E8%B0%83%E7%94%A8%20foo%22%5D%20--%3E%20P1%5B%22PLT%20%E6%A1%A9%20jmp%20GOT-foo%22%5D%0A%20%20P1%20--%3E%20SLOT1%5B%22GOT%20%E6%A7%BD%E6%8C%87%E5%90%91%E8%A7%A3%E6%9E%90%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SLOT1%20--%3E%20RES%5B%22%E5%8A%A8%E6%80%81%E9%93%BE%E6%8E%A5%E5%99%A8%E6%9F%A5%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20RES%20--%3E%20FILL%5B%22%E6%8A%8A%E7%9C%9F%E5%9C%B0%E5%9D%80%E5%86%99%E5%9B%9E%20GOT%22%5D%0A%20%20T2%5B%22%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%B0%83%E7%94%A8%20foo%22%5D%20--%3E%20P2%5B%22%E5%90%8C%E4%B8%80%20PLT%20%E6%A1%A9%22%5D%0A%20%20P2%20--%3E%20SLOT2%5B%22GOT%20%E5%B7%B2%E6%98%AF%E7%9C%9F%E5%9C%B0%E5%9D%80%22%5D%0A%20%20SLOT2%20--%3E%20REAL%5B%22%E7%9B%B4%E8%BE%BE%20libc%20%E9%87%8C%E7%9A%84%20foo%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p>不要把 PLT 当 C 的函数指针对象；函数指针值可能就是桩地址，比较与调用约定按 ABI。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不 <code>mmap</code>、不写 <code>ld.so</code> 算法细节、不处理 ifunc。后课默认：动态符号经 GOT/PLT。加载与动态链接把槽在运行时填上，并映射节进地址空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GOT 存地址；PLT 桩实现延迟绑定。</li><li>改写发生在 GOT，文本保持 PIC。</li><li>加载器下一课才跑；本课是表的布局。</li><li>出处：System V ABI；ELF；Levine, 2000。</li></ul>',5))])}const m=c(s,[["render",p]]);export{f as __pageData,m as default};
